const j = $input.first().json;
const ctx = $('Validate and Prepare Visual Binary').first().json;

let rawContent = j.choices?.[0]?.message?.content || j.output_text || '{}';
let parsed = {};
try {
  parsed = typeof rawContent === 'string' ? JSON.parse(rawContent) : rawContent;
} catch (e) {
  parsed = {
    routing: { visual_complexity: 'uncertain', reason_codes: ['PARSING_ERROR'] },
    analysis: { visual_text: String(rawContent).trim() }
  };
}

const routing = parsed.routing || {};
const complexity = String(routing.visual_complexity || 'simple').toLowerCase();
const isComplexOrUncertain = complexity === 'complex' || complexity === 'uncertain';

const lunaUsage = {
  provider: 'openai',
  model: 'gpt-5.6-luna',
  provider_request_id: j.id || null,
  input_tokens: j.usage?.prompt_tokens ?? null,
  output_tokens: j.usage?.completion_tokens ?? null,
  estimated_cost_usd: null,
  pricing_version: null
};

return [{
  json: {
    ...ctx,
    luna_parsed: parsed,
    luna_usage: lunaUsage,
    visual_complexity: complexity,
    needs_escalation: isComplexOrUncertain,
    selected_provider: isComplexOrUncertain ? 'gemini' : 'openai',
    selected_model: isComplexOrUncertain ? 'gemini-3.7-flash' : 'gpt-5.6-luna',
    escalated: isComplexOrUncertain,
    fallback_used: false
  },
  binary: $input.first().binary
}];

