const j = $input.first().json;
const triage = $('Evaluate Visual Triage Decision').first().json;

// Check if Gemini succeeded or errored
const hasGeminiError = Boolean(j.error || j.statusCode >= 400 || !j.candidates);

if (hasGeminiError) {
  // Trigger fallback to GPT-5.6 Terra
  return [{
    json: {
      ...triage,
      gemini_failed: true,
      needs_terra_fallback: true
    },
    binary: $input.first().binary
  }];
}

const rawGeminiText = j.candidates?.[0]?.content?.parts?.[0]?.text || '';
const geminiUsage = {
  provider: 'gemini',
  model: 'gemini-3.7-flash',
  provider_request_id: j.responseId || null,
  input_tokens: j.usageMetadata?.promptTokenCount ?? null,
  output_tokens: j.usageMetadata?.candidatesTokenCount ?? null,
  estimated_cost_usd: null,
  pricing_version: null
};

return [{
  json: {
    ...triage,
    selected_provider: 'gemini',
    selected_model: 'gemini-3.7-flash',
    final_visual_text: String(rawGeminiText).trim(),
    escalation_usage: geminiUsage,
    fallback_used: false
  }
}];

