const j = $input.first().json;
const prev = $('Handle Gemini Escalation Response').first().json;
const rawTerra = j.choices?.[0]?.message?.content || '';

const terraUsage = {
  provider: 'openai',
  model: 'gpt-5.6-terra',
  provider_request_id: j.id || null,
  input_tokens: j.usage?.prompt_tokens ?? null,
  output_tokens: j.usage?.completion_tokens ?? null,
  estimated_cost_usd: null,
  pricing_version: null
};

return [{
  json: {
    ...prev,
    selected_provider: 'openai',
    selected_model: 'gpt-5.6-terra',
    final_visual_text: String(rawTerra).trim(),
    escalation_usage: terraUsage,
    fallback_used: true
  }
}];

const item = $input.first().json;
const triage = item.luna_parsed || {};

let text = item.final_visual_text || triage.analysis?.visual_text || triage.analysis?.text || triage.visual_text || JSON.stringify(triage.analysis || triage);
if (!String(text).trim() || String(text).trim() === '{}') {
  throw new Error('EMPTY_VISION_ANALYSIS: Visual analysis yielded empty textual description');
}

const visualRoutingMetadata = {
  initial_provider: 'openai',
  initial_model: 'gpt-5.6-luna',
  classification: item.visual_complexity || 'simple',
  escalated: item.escalated || false,
  selected_provider: item.selected_provider || 'openai',
  selected_model: item.selected_model || 'gpt-5.6-luna',
  fallback_used: item.fallback_used || false
};

return [{
  json: {
    ...item,
    visual_text: String(text).trim(),
    visual_routing: visualRoutingMetadata
  }
}];

const norm = $('Normalize Vision Output').first().json;
const sourceRes = $('Persist Visual Source Text').first().json.res;
const stId = sourceRes.source_text_id || (typeof sourceRes === 'string' ? JSON.parse(sourceRes).source_text_id : null);
const usageId = $('Record Visual AI Usage').first().json.id;

return [{
  json: {
    ok: true,
    status: 'completed',
    ingestion_id: norm.ingestion_id,
    asset_id: norm.asset_id,
    source_text_id: stId,
    visual_text: norm.visual_text,
    visual_routing: norm.visual_routing,
    usage_id: usageId
  }
}];
